function relOk(r){const A=RELAR[r.i];if(isAr()&&!(A&&A.a))return false;if(S.nost&&RELX.has(r.i))return false;return true;}
function loveBag(k,n){S.lb=S.lb||{};let b=S.lb[k]||[];if(!b.length||b.some(i=>i>=n)){b=[...Array(n).keys()];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}}const v=b.pop();S.lb[k]=b;return v;}
function relPick(tags){const t=tags[Math.floor(Math.random()*tags.length)];let pool=REL.filter(r=>relOk(r)&&r.t.includes(t));if(!pool.length)pool=REL.filter(relOk);if(!pool.length)return null;return pool[loveBag('r'+t+(isAr()?'a':'')+(S.nost?'n':''),pool.length)];}
